(function () {
  'use strict';

  /* ================= 配置 ================= */
  var APP_ID = 'ersao_ward';
  var FILTER_MODE = 'mask';
  var SENSITIVE_WORDS = [
    '死亡','自杀','轻生','殉情','想死','去死',
    '自残','自伤','割腕','跳楼','上吊','安眠药','烧炭',
    '杀人','放火','杀死','焚烧','纵火',
    '傻逼','煞笔','滚蛋','他妈的'
  ];

  var TOPICS = [
    { group:'🎧 少年说', id:'kid_self',   speaker:'kid',    listener:'self',   tag:'致自己', listenerLabel:'对自己', title:'和自己说说话' },
    { group:'🎧 少年说', id:'kid_parent', speaker:'kid',    listener:'parent', tag:'致爸妈', listenerLabel:'对爸妈', title:'说不出口的话' },
    { group:'🎧 少年说', id:'kid_doc',    speaker:'kid',    listener:'doc',    tag:'致医护', listenerLabel:'对医护', title:'哥哥姐姐听我说' },
    { group:'🏠 爸妈说', id:'par_kid',    speaker:'parent', listener:'kid',    tag:'致孩子', listenerLabel:'对孩子', title:'爸妈想对你说' },
    { group:'🏠 爸妈说', id:'par_doc',    speaker:'parent', listener:'doc',    tag:'致医护', listenerLabel:'对医护', title:'想说给你们听' },
    { group:'🩺 医护说', id:'doc_kid',    speaker:'doc',    listener:'kid',    tag:'致孩子', listenerLabel:'对孩子', title:'看你们好起来真好' },
    { group:'🩺 医护说', id:'doc_par',    speaker:'doc',    listener:'parent', tag:'致家长', listenerLabel:'对家长', title:'我们是队友' }
  ];

  var SPEAKERS = [
    { key:'kid',    label:'少年', emoji:'🎧' },
    { key:'parent', label:'爸妈', emoji:'🏠' },
    { key:'doc',    label:'医护', emoji:'🩺' }
  ];

  var TOPIC_MAP = {};
  for (var _i = 0; _i < TOPICS.length; _i++) TOPIC_MAP[TOPICS[_i].id] = TOPICS[_i];

  var MAX_NEST_DEPTH = 3;
  var NICK_KEY = 'ersao_nick';
  var CLIENT_KEY = 'ersao_client_id';
  /* 送糖规则：只能送、不能收回；送出后 24 小时可再送一颗 */
  var LIKE_LOG_KEY = 'ersao_like_log';
  var LIKE_COOLDOWN_MS = 24 * 60 * 60 * 1000;

  /* ================= 本地存储 ================= */
  function lsGet(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
  function lsSet(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }

  function getClientId() {
    var id = lsGet(CLIENT_KEY);
    if (!id) {
      id = 'c_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
      lsSet(CLIENT_KEY, id);
    }
    return id;
  }
  function loadNick() { return lsGet(NICK_KEY) || ''; }

  function likeLog() {
    try {
      var o = JSON.parse(lsGet(LIKE_LOG_KEY) || '{}');
      return (o && typeof o === 'object' && !Array.isArray(o)) ? o : {};
    } catch (e) { return {}; }
  }
  function getLikeTs(id) {
    var n = Number(likeLog()[String(id)]);
    return (isFinite(n) && n > 0) ? n : 0;
  }
  function setLikeTs(id, ts) {
    var l = likeLog();
    l[String(id)] = ts;
    lsSet(LIKE_LOG_KEY, JSON.stringify(l));
  }
  function removeLikeTs(id) {
    var l = likeLog();
    delete l[String(id)];
    lsSet(LIKE_LOG_KEY, JSON.stringify(l));
  }
  function isCooling(id) {
    var ts = getLikeTs(id);
    return ts > 0 && (Date.now() - ts) < LIKE_COOLDOWN_MS;
  }
  function formatCooldownText(ms) {
    var totalMin = Math.max(1, Math.ceil(ms / 60000));
    var h = Math.floor(totalMin / 60), m = totalMin % 60;
    if (h > 0) return m > 0 ? (h + ' 小时 ' + m + ' 分钟') : (h + ' 小时');
    return m + ' 分钟';
  }

  /* ================= 工具 ================= */
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (m) {
      return { '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[m];
    });
  }
  function firstChar(s) {
    var t = String(s == null ? '' : s).trim();
    return t ? t.charAt(0) : '神';
  }
  function maskWords(text) {
    var out = String(text);
    for (var i = 0; i < SENSITIVE_WORDS.length; i++) {
      try {
        out = out.replace(
          new RegExp(SENSITIVE_WORDS[i].replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi'),
          '✱✱'
        );
      } catch (e) {}
    }
    return out;
  }
  function tsVal(c) {
    var t = c && c.created_at;
    if (typeof t === 'number') return t;
    var n = Number(t);
    if (isFinite(n) && n > 0) return n;
    var p = Date.parse(String(t || '').replace(' ', 'T'));
    return isNaN(p) ? 0 : p;
  }
  function formatTime(ts) {
    if (ts === null || ts === undefined || ts === '') return '';
    var t = Number(ts);
    if (!isFinite(t) || t <= 0) t = Date.parse(String(ts).replace(' ', 'T'));
    var d = new Date(t);
    if (isNaN(d.getTime())) return '';
    var p = function (n) { return n < 10 ? '0' + n : '' + n; };
    return d.getFullYear() + '/' + (d.getMonth() + 1) + '/' + d.getDate() + ' ' + p(d.getHours()) + ':' + p(d.getMinutes());
  }

  /* ================= 状态 ================= */
  var ALL = [], ROOTS = [], CHILDREN = {}, BY_ID = {};
  var currentRootId = null;
  var replyContext = null;
  var selectedTopicId = 'kid_self';
  var currentSpeaker = 'kid';
  var currentListener = 'self';

  function findComment(id) {
    if (id == null) return null;
    var k = String(id);
    return BY_ID[k] || BY_ID[Number(k)] || null;
  }

  /* ================= 送糖 ================= */
  function likeState(id) {
    var c = findComment(id);
    var count = 0, liked = false;
    if (c) {
      var n = Number(c.like_count);
      count = (isFinite(n) && n > 0) ? Math.floor(n) : 0;
      liked = !!c.liked_by_me;
    }
    if (getLikeTs(id) > 0) liked = true; // 本地记录过 → 永远保持已送
    return { liked: liked, count: count };
  }

  function likeButtonHtml(id, extraClass) {
    var st = likeState(id);
    var key = String(id);
    var cooling = isCooling(key) ? ' is-cooling' : '';
    return '<button class="like-btn' + (extraClass ? ' ' + extraClass : '') +
             (st.liked ? ' is-liked' : '') + cooling +
             '" data-id="' + esc(key) + '" type="button"' +
             ' aria-pressed="' + (st.liked ? 'true' : 'false') + '" aria-label="送一颗元气糖">' +
             '<span class="like-icon"></span><span class="like-count">' + st.count + '</span>' +
           '</button>';
  }

  function syncLikeButtons(id, liked, count) {
    var key = String(id);
    var cooling = isCooling(key);
    var btns = document.querySelectorAll('.like-btn');
    for (var i = 0; i < btns.length; i++) {
      var b = btns[i];
      if (b.getAttribute('data-id') !== key) continue;
      b.classList.toggle('is-liked', liked);
      b.classList.toggle('is-cooling', cooling);
      b.setAttribute('aria-pressed', liked ? 'true' : 'false');
      var num = b.querySelector('.like-count');
      if (num) num.textContent = count;
    }
  }

  function handleLike(id, btn) {
    if (!id || !btn) return;
    var key = String(id);
    if (btn.dataset.likePending === '1') return;

    var now = Date.now();
    var oldTs = getLikeTs(key);

    if (oldTs > 0 && now - oldTs < LIKE_COOLDOWN_MS) {
      toast('这颗糖已经送出去啦，' + formatCooldownText(LIKE_COOLDOWN_MS - (now - oldTs)) + '后再来送下一颗 ♡');
      return;
    }

    btn.dataset.likePending = '1';

    var prev = likeState(key);
    var nextCount = prev.count + 1;   // 永远 +1，永不 -1

    var c = findComment(key);
    if (c) { c.like_count = nextCount; c.liked_by_me = true; }
    setLikeTs(key, now);
    syncLikeButtons(key, true, nextCount);

    btn.classList.remove('is-pop');
    void btn.offsetWidth;
    btn.classList.add('is-pop');
    setTimeout(function () { btn.classList.remove('is-pop'); }, 560);

    function cleanup() { btn.dataset.likePending = ''; }
    function rollback() {
      var cc = findComment(key);
      if (cc) { cc.like_count = prev.count; cc.liked_by_me = prev.liked; }
      if (oldTs > 0) setLikeTs(key, oldTs); else removeLikeTs(key);
      syncLikeButtons(key, prev.liked, prev.count);
      toast('网络不太好，待会儿再试 ♡');
    }

    sendLikeRequest(key, 0, function (data) {
      if (!data) { rollback(); cleanup(); return; }

      if (data.cooling) {
        var remain = Number(data.retry_after_ms);
        if (isFinite(remain) && remain > 0 && remain <= LIKE_COOLDOWN_MS) {
          setLikeTs(key, Date.now() - (LIKE_COOLDOWN_MS - remain));
          toast('这颗糖刚刚才送过，' + formatCooldownText(remain) + '后再来送下一颗 ♡');
        }
      }

      var realCount = Number(data.like_count);
      if (!isFinite(realCount) || realCount < 0) realCount = nextCount;
      var realLiked = !!data.liked || getLikeTs(key) > 0;

      var cc = findComment(key);
      if (cc) { cc.like_count = realCount; cc.liked_by_me = realLiked; }
      syncLikeButtons(key, realLiked, realCount);
      cleanup();
    });
  }

  function sendLikeRequest(key, attempt, done) {
    fetch('/api/comments/' + encodeURIComponent(key) + '/like', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ client_id: getClientId() }),
      cache: 'no-store'
    })
      .then(function (res) {
        if (!res.ok) throw new Error('HTTP ' + res.status);
        return res.json();
      })
      .then(function (data) {
        // 兼容旧版「切换式」后端：若被当成取消，自动补发一次
        if (data && data.liked === false && attempt === 0) {
          sendLikeRequest(key, 1, done);
          return;
        }
        done(data || {});
      })
      .catch(function () { done(null); });
  }

  /* ================= Toast ================= */
  var toastTimer = null;
  function toast(msg) {
    var el = document.getElementById('toast');
    if (!el) {
      el = document.createElement('div');
      el.id = 'toast';
      document.body.appendChild(el);
    }
    el.textContent = msg;
    el.className = 'is-show';
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { el.className = ''; }, 2200);
  }

  /* ================= 话题 ================= */
  function topicsBySpeaker(speaker) {
    var out = [];
    for (var i = 0; i < TOPICS.length; i++) {
      if (TOPICS[i].speaker === speaker) out.push(TOPICS[i]);
    }
    return out;
  }
  function findTopic(speaker, listener) {
    for (var i = 0; i < TOPICS.length; i++) {
      if (TOPICS[i].speaker === speaker && TOPICS[i].listener === listener) return TOPICS[i];
    }
    return null;
  }
  function applyTopic(speaker, listener) {
    var t = findTopic(speaker, listener);
    if (!t) return;
    currentSpeaker = speaker;
    currentListener = listener;
    selectedTopicId = t.id;
  }

  /* ================= 拉取数据 ================= */
  function fetchTopic(t) {
    return fetch(
      '/api/comments?app_id=' + encodeURIComponent(APP_ID) +
      '&topic_id=' + encodeURIComponent(t.id) +
      '&client_id=' + encodeURIComponent(getClientId()),
      { cache: 'no-store' }
    )
      .then(function (res) {
        if (!res.ok) return [];
        return res.json().then(function (data) {
          var arr = Array.isArray(data) ? data : (data && Array.isArray(data.comments) ? data.comments : []);
          return arr.map(function (c) {
            c.topic_id = t.id;
            // 从服务器恢复冷却计时（换设备/清缓存后仍可提示剩余时间）
            var lastAt = Number(c.my_last_like_at);
            if (isFinite(lastAt) && lastAt > 0 && !getLikeTs(c.id)) setLikeTs(c.id, lastAt);
            return c;
          });
        });
      })
      .catch(function () { return []; });
  }

  function fetchAllComments() {
    return Promise.all(TOPICS.map(fetchTopic)).then(function (results) {
      var all = [];
      for (var i = 0; i < results.length; i++) {
        for (var j = 0; j < results[i].length; j++) all.push(results[i][j]);
      }
      all.sort(function (a, b) { return tsVal(a) - tsVal(b); });

      BY_ID = {};
      CHILDREN = {};
      for (var k = 0; k < all.length; k++) {
        var c = all[k];
        c.__key = String(c.id);
        c.parent_id = (c.parent_id == null || c.parent_id === '') ? null : c.parent_id;
        BY_ID[c.__key] = c;
        if (c.parent_id) {
          var pk = String(c.parent_id);
          (CHILDREN[pk] || (CHILDREN[pk] = [])).push(c);
        }
      }
      ALL = all;
      ROOTS = all.filter(function (c) {
        return !c.parent_id || !BY_ID[String(c.parent_id)];
      });
      return all;
    });
  }

  function countReplies(id) {
    var kids = CHILDREN[String(id)] || [];
    var n = 0;
    for (var i = 0; i < kids.length; i++) n += 1 + countReplies(kids[i].id);
    return n;
  }

  function pickRandom() {
    if (!ROOTS.length) return null;
    var pool = ROOTS.filter(function (r) { return String(r.id) !== String(currentRootId); });
    var list = pool.length ? pool : ROOTS;
    return list[Math.floor(Math.random() * list.length)];
  }

  /* ================= 渲染 ================= */
  function renderNote(root) {
    var card = document.getElementById('noteCard');
    if (!root) {
      card.innerHTML =
        '<div class="note-empty">' +
          '<div class="note-empty-icon">🛒</div>' +
          '<p>货架还空着。<br>来放第一条心里话吧～</p>' +
        '</div>';
      return;
    }

    var topic = TOPIC_MAP[root.topic_id] || {};
    var nick = root.nick || '神秘顾客';
    var total = countReplies(root.id);

    card.innerHTML =
      '<div class="note-top">' +
        (topic.tag ? '<span class="note-tag">' + esc(topic.tag) + '</span>' : '') +
        (topic.group ? '<span class="note-group">' + esc(topic.group) + '</span>' : '') +
      '</div>' +
      '<div class="note-main">' +
        '<div class="note-avatar">' + esc(firstChar(nick)) + '</div>' +
        '<div class="note-main-body">' +
          '<div class="note-nick">' +
            '<span>' + esc(nick) + '</span>' +
            '<span class="note-time">' + formatTime(root.created_at) + '</span>' +
          '</div>' +
          '<div class="note-text">' + esc(root.content) + '</div>' +
        '</div>' +
      '</div>' +
      '<div class="note-foot">' +
        '<div class="note-foot-actions">' +
          likeButtonHtml(root.id, '') +
          '<button class="reply-btn" data-id="' + esc(root.id) + '" data-nick="' + esc(nick) + '" type="button">↩ 回复</button>' +
        '</div>' +
        '<span class="reply-count">' + (total ? '💬 ' + total + ' 条回声' : '还没有回声') + '</span>' +
      '</div>' +
      renderReplies(root.id, 1);

    bindCardActions(card);
  }

  function renderReplies(parentId, depth) {
    var kids = CHILDREN[String(parentId)] || [];
    if (!kids.length) return '';
    var flat = depth >= MAX_NEST_DEPTH;
    var html = '<div class="replies' + (flat ? ' replies--flat' : '') + '">';
    for (var i = 0; i < kids.length; i++) html += renderReply(kids[i], depth);
    return html + '</div>';
  }

  function renderReply(c, depth) {
    var nick = c.nick || '神秘顾客';
    var parent = c.parent_id ? BY_ID[String(c.parent_id)] : null;
    var replyTo = parent
      ? '<span class="reply-to">回复 @' + esc(parent.nick || '神秘顾客') + '：</span>'
      : '';
    return '<div class="reply-item">' +
        '<div class="reply-avatar">' + esc(firstChar(nick)) + '</div>' +
        '<div class="reply-main">' +
          '<div class="reply-head">' +
            '<span class="reply-nick">' + esc(nick) + '</span>' +
            '<span class="reply-time">' + formatTime(c.created_at) + '</span>' +
          '</div>' +
          '<div class="reply-text">' + replyTo + esc(c.content) + '</div>' +
          '<div class="reply-actions">' +
            likeButtonHtml(c.id, 'like-btn--sm') +
            '<button class="reply-btn" data-id="' + esc(c.id) + '" data-nick="' + esc(nick) + '" type="button">回复</button>' +
          '</div>' +
          renderReplies(c.id, depth + 1) +
        '</div>' +
      '</div>';
  }

  function bindCardActions(scope) {
    var btns = scope.querySelectorAll('.reply-btn, .like-btn');
    for (var i = 0; i < btns.length; i++) {
      (function (b) {
        if (b.classList.contains('reply-btn')) {
          b.onclick = function () {
            openReply(b.getAttribute('data-id'), b.getAttribute('data-nick'));
          };
        } else {
          b.onclick = function (e) {
            if (e && e.stopPropagation) e.stopPropagation();
            handleLike(b.getAttribute('data-id'), b);
          };
        }
      })(btns[i]);
    }
  }

  function showRoot(root) {
    currentRootId = root ? root.id : null;
    renderNote(root);
  }

  function updateShelfTitle() {
    document.getElementById('shelfTitle').textContent =
      ROOTS.length ? '货架上的心里话 · 共 ' + ROOTS.length + ' 条' : '货架上的心里话';
  }

  function onNext() {
    if (!ROOTS.length) { toast('货架还空着，来写第一条吧 ✎'); return; }
    var pool = ROOTS.filter(function (r) { return String(r.id) !== String(currentRootId); });
    if (!pool.length) { toast('就这一条啦，写点新的吧 ✎'); return; }

    var next = pool[Math.floor(Math.random() * pool.length)];
    var card = document.getElementById('noteCard');
    card.classList.add('is-fading');
    setTimeout(function () {
      showRoot(next);
      card.classList.remove('is-fading');
    }, 220);
  }

  /* ================= 回复 ================= */
  function openReply(id, nick) {
    var target = findComment(id);
    if (!target) { toast('这条留言已经不在了'); return; }
    replyContext = { targetId: target.id, topicId: target.topic_id, nick: nick || target.nick || '神秘顾客' };
    document.getElementById('replyModalTitle').textContent = '回复 @' + replyContext.nick;
    document.getElementById('replyNick').value = loadNick();
    document.getElementById('replyContent').value = '';
    openModal('replyModal', document.getElementById('replyContent'));
  }

  function handleReplySubmit() {
    if (!replyContext || !replyContext.targetId || !replyContext.topicId) {
      toast('找不到要回复的留言了');
      return;
    }
    var nickRaw = document.getElementById('replyNick').value.trim() || '神秘顾客';
    var contentRaw = document.getElementById('replyContent').value.trim();
    if (!contentRaw) { toast('写点什么再上架吧'); return; }

    var ctx = replyContext;

    function send(content, nick) {
      var btn = document.getElementById('replySubmit');
      submitComment({ topicId: ctx.topicId, parentId: ctx.targetId, nick: nick, content: content }, btn)
        .then(function (ok) {
          if (!ok) return;
          lsSet(NICK_KEY, nick);
          document.getElementById('replyContent').value = '';
          closeModal('replyModal');
          replyContext = null;
          return refreshKeepCurrent().then(function () { toast('回声已上架 🌱'); });
        });
    }

    if (FILTER_MODE === 'mask') {
      var mc = maskWords(contentRaw), mn = maskWords(nickRaw);
      if (mc !== contentRaw || mn !== nickRaw) {
        showMaskConfirm(mc, mn, function () { send(mc, mn); });
        return;
      }
    }
    send(contentRaw, nickRaw);
  }

  /* ================= 写留言 ================= */
  function renderTopicPicker() {
    var picker = document.getElementById('topicPicker');
    var html = '<div class="picker-step">' +
      '<div class="picker-step-title"><span class="step-num">1</span>我是谁</div>' +
      '<div class="speaker-chips">';

    for (var s = 0; s < SPEAKERS.length; s++) {
      var sp = SPEAKERS[s];
      html += '<button class="speaker-chip' + (sp.key === currentSpeaker ? ' is-active' : '') +
              '" data-speaker="' + esc(sp.key) + '" type="button">' +
                '<span class="emoji">' + sp.emoji + '</span><span>' + esc(sp.label) + '</span>' +
              '</button>';
    }
    html += '</div></div>';

    var candidates = topicsBySpeaker(currentSpeaker);
    html += '<div class="picker-step">' +
      '<div class="picker-step-title"><span class="step-num">2</span>我想对谁说</div>' +
      '<div class="listener-chips">';
    for (var l = 0; l < candidates.length; l++) {
      var c = candidates[l];
      html += '<button class="listener-chip' + (c.listener === currentListener ? ' is-active' : '') +
              '" data-listener="' + esc(c.listener) + '" type="button">' + esc(c.listenerLabel) + '</button>';
    }
    html += '</div></div>';

    var current = TOPIC_MAP[selectedTopicId] || TOPICS[0];
    html += '<div class="picker-preview"><span>将放进：</span>' +
            '<span class="preview-value">' + esc(current.group) + ' · ' + esc(current.tag) + '</span></div>';

    picker.innerHTML = html;

    var speakerBtns = picker.querySelectorAll('.speaker-chip');
    for (var a = 0; a < speakerBtns.length; a++) {
      speakerBtns[a].onclick = function () {
        var sp = this.getAttribute('data-speaker');
        var cands = topicsBySpeaker(sp);
        if (!cands.length) return;
        if (findTopic(sp, currentListener)) applyTopic(sp, currentListener);
        else applyTopic(sp, cands[0].listener);
        renderTopicPicker();
      };
    }

    var listenerBtns = picker.querySelectorAll('.listener-chip');
    for (var b = 0; b < listenerBtns.length; b++) {
      listenerBtns[b].onclick = function () {
        applyTopic(currentSpeaker, this.getAttribute('data-listener'));
        renderTopicPicker();
      };
    }
  }

  function openWrite() {
    document.getElementById('writeNick').value = loadNick();
    document.getElementById('writeContent').value = '';
    renderTopicPicker();
    openModal('writeModal', document.getElementById('writeContent'));
  }

  function handleWriteSubmit() {
    var nickRaw = document.getElementById('writeNick').value.trim() || '神秘顾客';
    var contentRaw = document.getElementById('writeContent').value.trim();
    if (!selectedTopicId) { toast('先选一下「我是谁 / 对谁说」吧'); return; }
    if (!contentRaw) { toast('写点什么再上架吧'); return; }

    function send(content, nick) {
      var btn = document.getElementById('writeSubmit');
      var beforeIds = {};
      for (var i = 0; i < ROOTS.length; i++) beforeIds[String(ROOTS[i].id)] = 1;

      submitComment({ topicId: selectedTopicId, parentId: null, nick: nick, content: content }, btn)
        .then(function (ok) {
          if (!ok) return;
          lsSet(NICK_KEY, nick);
          document.getElementById('writeContent').value = '';
          closeModal('writeModal');
          return fetchAllComments().then(function () {
            updateShelfTitle();
            var mine = null;
            for (var j = 0; j < ROOTS.length; j++) {
              if (!beforeIds[String(ROOTS[j].id)]) { mine = ROOTS[j]; break; }
            }
            showRoot(mine || pickRandom());
            toast('上架啦，谢谢你的分享 🌱');
          });
        });
    }

    if (FILTER_MODE === 'mask') {
      var mc = maskWords(contentRaw), mn = maskWords(nickRaw);
      if (mc !== contentRaw || mn !== nickRaw) {
        showMaskConfirm(mc, mn, function () { send(mc, mn); });
        return;
      }
    }
    send(contentRaw, nickRaw);
  }

  /* ================= 提交 / 刷新 ================= */
  function submitComment(data, btn) {
    var oldLabel = btn ? btn.textContent : '';
    if (btn) { btn.disabled = true; btn.textContent = '上架中…'; }

    return fetch('/api/comments', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        app_id: APP_ID,
        topic_id: data.topicId,
        parent_id: data.parentId,
        nick: data.nick,
        content: data.content
      }),
      cache: 'no-store'
    })
      .then(function (res) {
        if (!res.ok) throw new Error('HTTP ' + res.status);
        return res.json().catch(function () { return {}; });
      })
      .then(function () { return true; })
      .catch(function () {
        toast('网络不太好，没发出去，再试一次 ♡');
        return false;
      })
      .then(function (ok) {
        if (btn) { btn.disabled = false; btn.textContent = oldLabel; }
        return ok;
      });
  }

  function refreshKeepCurrent() {
    var keepId = currentRootId;
    return fetchAllComments().then(function () {
      updateShelfTitle();
      var root = keepId != null ? findComment(keepId) : null;
      showRoot(root || pickRandom());
    });
  }

  /* ================= 弹窗 ================= */
  function openModal(id, focusEl) {
    var overlay = document.getElementById(id);
    if (!overlay) return;
    overlay.classList.add('is-open');
    if (focusEl) {
      setTimeout(function () { try { focusEl.focus(); } catch (e) {} }, 380);
    }
  }
  function closeModal(id) {
    var overlay = document.getElementById(id);
    if (!overlay) return;
    overlay.classList.remove('is-open');
    var a = document.activeElement;
    if (a && (a.tagName === 'INPUT' || a.tagName === 'TEXTAREA')) a.blur();
  }

  /* 敏感词打码确认弹窗（动态创建） */
  var maskModalEl = null;
  function showMaskConfirm(maskedContent, maskedNick, onConfirm) {
    if (!maskModalEl) {
      maskModalEl = document.createElement('div');
      maskModalEl.className = 'modal-overlay modal-overlay--center';
      maskModalEl.id = 'maskModal';
      maskModalEl.innerHTML =
        '<div class="concept-card" style="max-width:360px">' +
          '<div class="concept-icon">🛡️</div>' +
          '<h3 class="concept-title">小提醒</h3>' +
          '<div class="concept-subtitle">有些词我们轻轻挡了一下，发出前先看看～</div>' +
          '<div id="maskPreview" style="font-size:.85rem;line-height:1.8;color:var(--soft);background:#fff;border-radius:14px;padding:.85rem;border:1px dashed rgba(255,123,92,.35);white-space:pre-wrap;word-break:break-word;margin-bottom:.9rem;max-height:40vh;overflow-y:auto"></div>' +
          '<div style="display:flex;gap:.6rem">' +
            '<button type="button" id="maskCancel" style="flex:1;padding:.68rem;border-radius:999px;font-weight:700;font-size:.9rem;color:var(--mute);background:#fff;box-shadow:inset 0 0 0 1.5px rgba(160,130,100,.2)">改一改</button>' +
            '<button type="button" id="maskOk" style="flex:1.3;padding:.68rem;border-radius:999px;font-weight:700;font-size:.9rem;color:#fff;background:linear-gradient(135deg,#ffb347,#ff7b5c 48%,#ff6b9d);box-shadow:0 10px 22px -8px rgba(255,107,157,.65)">就这样发</button>' +
          '</div>' +
        '</div>';
      document.body.appendChild(maskModalEl);
      document.getElementById('maskCancel').onclick = function () {
        maskModalEl.classList.remove('is-open');
      };
      document.getElementById('maskOk').onclick = function () {
        maskModalEl.classList.remove('is-open');
        var fn = maskModalEl.__onConfirm;
        maskModalEl.__onConfirm = null;
        if (fn) fn();
      };
    }
    document.getElementById('maskPreview').textContent = '【' + maskedNick + '】\n\n' + maskedContent;
    maskModalEl.__onConfirm = onConfirm;
    maskModalEl.classList.add('is-open');
  }

  /* ================= 初始化 ================= */
  function init() {
    /* 日期 */
    var d = new Date();
    var weeks = ['日', '一', '二', '三', '四', '五', '六'];
    document.getElementById('todayDate').textContent =
      (d.getMonth() + 1) + '月' + d.getDate() + '日 · 周' + weeks[d.getDay()];

    /* 底部操作 */
    document.getElementById('nextBtn').onclick = onNext;
    document.getElementById('writeBtn').onclick = openWrite;
    document.getElementById('openConceptBtn').onclick = function () { openModal('conceptModal'); };
    document.getElementById('replySubmit').onclick = handleReplySubmit;
    document.getElementById('writeSubmit').onclick = handleWriteSubmit;

    /* ---------- 背景音乐 ---------- */
    var bgm = document.getElementById('bgm');
    var musicBtn = document.getElementById('musicBtn');
    var bgmUserPaused = false;
    bgm.loop = true;

    function setMusicUI(on) {
      musicBtn.classList.toggle('is-on', on);
      musicBtn.textContent = on ? '♫' : '♪';
      var label = on ? '暂停背景音乐' : '播放背景音乐';
      musicBtn.setAttribute('aria-label', label);
      musicBtn.title = label;
    }

    function playBgm() {
      if (!bgm.paused) { setMusicUI(true); return Promise.resolve(true); }
      var p;
      try { p = bgm.play(); } catch (e) { p = null; }
      if (!p || typeof p.then !== 'function') { setMusicUI(true); return Promise.resolve(true); }
      return p.then(function () { setMusicUI(true); return true; })
              .catch(function () { setMusicUI(false); return false; });
    }

    // 任意点击 / 触摸 / 按键都尝试播放（浏览器策略要求必须在用户操作里调用）
    function autoPlayBgm() {
      if (bgmUserPaused || !bgm.paused) return;
      playBgm();
    }
    ['click', 'touchstart', 'pointerdown', 'keydown'].forEach(function (evt) {
      document.addEventListener(evt, autoPlayBgm, { passive: true });
    });

    musicBtn.addEventListener('click', function (e) {
      e.stopPropagation();
      if (e.preventDefault) e.preventDefault();
      if (bgm.paused) {
        bgmUserPaused = false;
        playBgm().then(function (ok) { if (!ok) toast('音乐还没准备好，稍后再试试 ♪'); });
      } else {
        bgmUserPaused = true;
        bgm.pause();
        setMusicUI(false);
      }
    });

    setMusicUI(false);

    /* 弹窗关闭：事件委托 */
    document.addEventListener('click', function (e) {
      var t = e.target;
      if (!t || !t.classList) return;
      if (t.classList.contains('modal-overlay') && t.classList.contains('is-open')) {
        closeModal(t.id);
      }
      var closeId = t.getAttribute && t.getAttribute('data-close');
      if (closeId) closeModal(closeId);
    });

    /* Esc 关闭 */
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' || e.keyCode === 27) {
        var opens = document.querySelectorAll('.modal-overlay.is-open');
        for (var i = 0; i < opens.length; i++) opens[i].classList.remove('is-open');
      }
    });

    /* 键盘弹起时收起底部栏 */
    document.addEventListener('focusin', function (e) {
      var tag = e.target && e.target.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA') document.body.classList.add('keyboard-open');
    });
    document.addEventListener('focusout', function () {
      setTimeout(function () {
        var a = document.activeElement, tag = a && a.tagName;
        if (tag !== 'INPUT' && tag !== 'TEXTAREA') document.body.classList.remove('keyboard-open');
      }, 80);
    });

    /* 首次加载货架 */
    fetchAllComments().then(function () {
      updateShelfTitle();
      showRoot(pickRandom());
    });
  }

  init();
})();
